// TASK-0047 — V1 Accessibility Closure, product acceptance in the real WebView2 (`DEC-0045`).
// No simulated DOM, no alternate renderer, no personal data: the trees under test were generated by
// task0047-seed-proof.py and die with the proof root.
//
// argv: <cdp port> <variant> <mode: baseline|final> <artifact path>. The seed travels on stdin.
//
// What this proves, in the REAL engine:
//   1  axe-core (the devDependency of `node_modules`, injected into the page: never bundled, never
//      fetched) on every state of the matrix — FR and EN, light and dark (the scheme is emulated in
//      the engine), the initial screen, the composition menu, the identity editor, a folder-backed
//      brain with every panel open, the synthetic brain with content / relations / review / duplicates,
//      a two-brain composition, reduced motion. Violations AND `incomplete` are published.
//   2  (final) a keyboard walk made only of real input events (CDP Input.dispatchKeyEvent): Tab and
//      Shift+Tab reach every tabbable element in a coherent order and leave the page; the focus
//      indicator is proved VISIBLE by pixels (screenshot of the focused element compared with the
//      same element blurred); Enter / Space activate; the menu, the tree, the editor, the search, the
//      filters, the journal, the details, the review queue and the duplicates explorer are used.
//   3  (final) contrast measured from the computed styles of the real elements (a sweep of every
//      text node + the non-text components), independent of axe.
//   4  (final) every visual coding has a non-colour alternative read off the real screen.
//   5  (final) `prefers-reduced-motion: reduce` emulated: the computed styles of what moves in the
//      normal mode.
//   6  (final) the invariants: no backend command from the audit / the walk / the emulation, the
//      SHA-256 of both roots before and after, the Index and journal counters, the resume records.
//
// Baseline mode publishes what axe finds and judges nothing.
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { mkdir, readdir, readFile, stat, writeFile } from "node:fs/promises";
import { setTimeout as pause } from "node:timers/promises";
import { join, relative } from "node:path";

const port = Number(process.argv[2]);
const variant = process.argv[3];
const MODE = process.argv[4];
const artifactPath = process.argv[5];
assert(/^task0047-[a-f0-9]+$/.test(variant));
assert(["baseline", "final"].includes(MODE));
// Both modes run EVERY stage. `final` judges (any problem fails the run); `baseline`, run on the code as it
// was BEFORE the corrections, publishes the same findings without judging them.
const FINAL = true;
const JUDGE = MODE === "final";

const seed = JSON.parse(
  (
    await new Promise((resolve, reject) => {
      let text = "";
      process.stdin.setEncoding("utf8");
      process.stdin.on("data", (c) => (text += c));
      process.stdin.on("end", () => resolve(text));
      process.stdin.on("error", reject);
    })
  ).replace(/^﻿/, ""), // PowerShell's pipe prepends a UTF-8 BOM.
);
/** A: the folder-backed brain of the seed. S: the built-in synthetic brain (the fixture `quasi-empty`). */
const IDS = { A: seed.brainA, S: "brain-alpha", B: seed.brainB };
const ROOTS = [seed.rootAlix, seed.rootBasile];
const proofRoot = join(".filetopo-sandbox", variant);

