await send("Network.enable", { maxTotalBufferSize: 64 * 1024 * 1024, maxResourceBufferSize: 16 * 1024 * 1024 });

// ---- real input ---------------------------------------------------------------------
const centerOf = (selector) =>
  evaluate(`(() => {
    const e = document.querySelector(${JSON.stringify(selector)});
    if (!e) return null;
    e.scrollIntoView?.({ block: 'center', inline: 'center' });
    const r = e.getBoundingClientRect();
    const x = r.x + r.width / 2;
    const y = r.y + r.height / 2;
    const top = document.elementFromPoint(x, y);
    return {
      x, y, w: r.width, h: r.height,
      hit: !!top && (e === top || e.contains(top) || top.contains(e)),
      topmost: top ? (top.getAttribute('data-testid') || top.tagName) : null,
    };
  })()`);
/** One real left click (move, press, release) at the middle of the element. */
async function click(selector) {
  const box = await centerOf(selector);
  assert(box && box.w > 0 && box.h > 0, `click: nothing clickable at ${selector}`);
  assert(box.hit, `click: ${selector} is covered by ${box.topmost} at (${Math.round(box.x)}, ${Math.round(box.y)})`);
  await send("Input.dispatchMouseEvent", { type: "mouseMoved", x: box.x, y: box.y });
  await send("Input.dispatchMouseEvent", { type: "mousePressed", x: box.x, y: box.y, button: "left", buttons: 1, clickCount: 1 });
  await send("Input.dispatchMouseEvent", { type: "mouseReleased", x: box.x, y: box.y, button: "left", buttons: 0, clickCount: 1 });
  await pause(200);
}
/** The keys the walk uses, as the browser's own input pipeline wants them. */
const KEYS = {
  Tab: { key: "Tab", code: "Tab", vk: 9 },
  Enter: { key: "Enter", code: "Enter", vk: 13, text: "\r" },
  Escape: { key: "Escape", code: "Escape", vk: 27 },
  " ": { key: " ", code: "Space", vk: 32, text: " " },
  ArrowUp: { key: "ArrowUp", code: "ArrowUp", vk: 38 },
  ArrowDown: { key: "ArrowDown", code: "ArrowDown", vk: 40 },
  ArrowLeft: { key: "ArrowLeft", code: "ArrowLeft", vk: 37 },
  ArrowRight: { key: "ArrowRight", code: "ArrowRight", vk: 39 },
  Backspace: { key: "Backspace", code: "Backspace", vk: 8 },
  Home: { key: "Home", code: "Home", vk: 36 },
  End: { key: "End", code: "End", vk: 35 },
  "+": { key: "+", code: "Equal", vk: 187, text: "+", shiftKey: true },
  "-": { key: "-", code: "Minus", vk: 189, text: "-" },
};
/** One REAL key press (down + up) through the browser's input pipeline. `modifiers`: 1 Alt, 2 Ctrl, 4 Meta, 8 Shift. */
async function press(name, { shift = false, alt = false } = {}) {
  const k = KEYS[name] ?? { key: name, code: /^[a-z]$/i.test(name) ? `Key${name.toUpperCase()}` : name, vk: name.toUpperCase().charCodeAt(0), text: name };
  const modifiers = (alt ? 1 : 0) | (shift || k.shiftKey ? 8 : 0);
  const down = { type: k.text ? "keyDown" : "rawKeyDown", key: k.key, code: k.code, windowsVirtualKeyCode: k.vk, nativeVirtualKeyCode: k.vk, modifiers };
  if (k.text) {
    down.text = k.text;
    down.unmodifiedText = k.text;
  }
  await send("Input.dispatchKeyEvent", down);
  await send("Input.dispatchKeyEvent", { type: "keyUp", key: k.key, code: k.code, windowsVirtualKeyCode: k.vk, nativeVirtualKeyCode: k.vk, modifiers });
  await pause(90);
}
async function selectAll() {
  await send("Input.dispatchKeyEvent", {
    type: "keyDown", modifiers: 2, key: "a", code: "KeyA", windowsVirtualKeyCode: 65, nativeVirtualKeyCode: 65, commands: ["selectAll"],
  });
  await send("Input.dispatchKeyEvent", { type: "keyUp", modifiers: 2, key: "a", code: "KeyA", windowsVirtualKeyCode: 65, nativeVirtualKeyCode: 65 });
}
async function typeText(text) {
  for (const ch of Array.from(text)) {
    await send("Input.dispatchKeyEvent", { type: "keyDown", key: ch, text: ch, unmodifiedText: ch });
    await send("Input.dispatchKeyEvent", { type: "keyUp", key: ch });
    await pause(25);
  }
  await pause(150);
}
async function clickButtonByText(pattern) {
  const point = await evaluate(`(() => {
    const re = new RegExp(${JSON.stringify(pattern.source)});
    const b = [...document.querySelectorAll('button')].find((x) => re.test(x.textContent.trim()) && !x.disabled);
    if (!b) return null;
    b.scrollIntoView({ block: 'center' });
    const r = b.getBoundingClientRect();
    return { x: r.x + r.width / 2, y: r.y + r.height / 2 };
  })()`);
  assert(point, `no enabled button matches ${pattern}`);
  await send("Input.dispatchMouseEvent", { type: "mouseMoved", x: point.x, y: point.y });
  await send("Input.dispatchMouseEvent", { type: "mousePressed", x: point.x, y: point.y, button: "left", buttons: 1, clickCount: 1 });
  await send("Input.dispatchMouseEvent", { type: "mouseReleased", x: point.x, y: point.y, button: "left", buttons: 0, clickCount: 1 });
  await pause(400);
}
