const slimResults = (list) =>
  list.map((rule) => ({
    ruleId: rule.id,
    impact: rule.impact ?? null,
    help: rule.help,
    tags: rule.tags.filter((tag) => /^wcag|^best-practice/.test(tag)),
    nodes: rule.nodes.map((node) => ({
      target: node.target,
      html: node.html.slice(0, 260),
      messages: [...node.any, ...node.all, ...node.none].map((check) => check.message).filter(Boolean).slice(0, 3),
      data: [...node.any, ...node.all, ...node.none]
        .map((check) => check.data)
        .filter((d) => d && typeof d === "object" && Object.keys(d).length > 0)
        .map((d) => JSON.parse(JSON.stringify(d, (k, v) => (typeof v === "string" ? v.slice(0, 160) : v))))
        .slice(0, 2),
    })),
  }));
async function axeRun(extraOptions = {}) {
  const raw = await evaluate(`(async () => {
    const r = await axe.run(document, Object.assign({
      runOnly: { type: 'tag', values: ${JSON.stringify(AXE_TAGS)} },
      resultTypes: ['violations', 'incomplete', 'passes'],
    }, ${JSON.stringify(extraOptions)}));
    return { violations: r.violations, incomplete: r.incomplete, passes: r.passes.map((p) => p.id), inapplicable: r.inapplicable.map((p) => p.id), url: r.url,
      environment: { userAgent: r.testEnvironment.userAgent, width: r.testEnvironment.windowWidth, height: r.testEnvironment.windowHeight } };
  })()`);
  return {
    violations: slimResults(raw.violations),
    incomplete: slimResults(raw.incomplete),
    passedRules: [...raw.passes].sort(),
    inapplicableRules: [...raw.inapplicable].sort(),
    viewport: raw.environment,
  };
}

