/** The map, as a keyboard-operable tree: every pointer gesture (select, pan, zoom) has a key. */
async function journeyTree() {
  const j = journey("map-tree", "the map (role=tree) reached by Tab: arrows walk parent / child / siblings, Home = root, + / - zoom, f fit, r reset, Alt+arrows pan, n / p step territories");
  await focusStart();
  await j.tab(testid("composed-canvas"));
  const read = () =>
    evaluate(`(() => {
      const t = document.querySelector('[data-testid="composed-canvas"]');
      const id = t.getAttribute('aria-activedescendant');
      const target = id ? document.getElementById(id) : null;
      const world = document.querySelector('[data-testid="composed-world"]');
      return { activedescendant: id, targetExists: !!target, selectedIsIt: target ? target.getAttribute('aria-selected') === 'true' : null, world: world ? world.getAttribute('transform') : null, detail: document.querySelector('.details__name')?.textContent ?? null };
    })()`);
  const homeBefore = await read();
  await j.key("Home", read);
  const home = await read();
  check(home.targetExists && home.selectedIsIt, `tree: Home did not select a drawn root (${JSON.stringify(home)})`);
  await j.key("ArrowRight", read);
  const child = await read();
  check(child.activedescendant !== home.activedescendant && child.targetExists && child.selectedIsIt, "tree: ArrowRight did not move the selection to a child");
  await j.key("ArrowDown", read);
  const sibling = await read();
  check(sibling.targetExists, "tree: ArrowDown left the tree without a drawn active descendant");
  await j.key("ArrowLeft", read);
  await j.key("ArrowLeft", read);
  const back = await read();
  check(back.targetExists && back.selectedIsIt, "tree: ArrowLeft did not come back to a drawn ancestor");
  const worldNow = (await read()).world;
  await j.key("+", read);
  const zoomed = (await read()).world;
  check(zoomed !== worldNow, "tree: « + » did not zoom the map");
  await j.key("-", read);
  const unzoomed = (await read()).world;
  check(unzoomed !== zoomed, "tree: « - » did not zoom back");
  await j.key("f", read);
  await j.key("r", read);
  await j.key("+", read);
  await j.key("+", read);
  await j.key("+", read);
  const beforePan = (await read()).world;
  await j.key("ArrowLeft", read, { alt: true });
  await j.key("ArrowDown", read, { alt: true });
  const panned = (await read()).world;
  check(panned !== beforePan, "tree: Alt+arrows did not pan the zoomed map");
  await j.key("r", read);
  if ((await screenSelection()).chips.length > 1) {
    const at = (await read()).activedescendant;
    await j.key("n", read);
    check((await read()).activedescendant !== at, "tree: « n » did not step to the next territory");
    await j.key("p", read);
  }
  void homeBefore;
  await j.key("Tab", async () => ({ leftTheTree: !(await activeIs(testid("composed-canvas"))) }));
  check(!(await activeIs(testid("composed-canvas"))), "tree: Tab did not leave the map (trap)");
}
/**
 * The controls that carry the pointer's « go to this node » gestures, used by keyboard alone: each is a native button
 * reached by Tab and activated by Enter, and the screen must answer (the selection, the detail or the status moves).
 */
async function journeyNavigation(label, targets, prepare = null) {
  const j = journey(`navigation-controls: ${label}`, "the buttons that navigate to a node (details children, filter results, journal events, relations, duplicate members, inter-brain relations), operated with Tab + Enter");
  const signature = async () => JSON.stringify({ selected: (await screenSelection()).selectedId, detail: await evaluate(`document.querySelector('.details__name')?.textContent ?? null`), status: await evaluate(`document.querySelector('.app__status')?.textContent ?? ''`), chips: (await screenSelection()).chips });
  if (prepare) await prepare();
  for (const { name, selector } of targets) {
    const count = await evaluate(`document.querySelectorAll(${JSON.stringify(selector)}).length`);
    if (count === 0) {
      j.note(`${name}: none on screen in this state`);
      continue;
    }
    // a candidate that is NOT the current selection, so that activating it has to change something
    const selectedId = (await screenSelection()).selectedId;
    const expression = `document.activeElement.matches(${JSON.stringify(selector)}) && (document.activeElement.getAttribute('data-node-id') ?? document.activeElement.getAttribute('data-endpoint-node-id') ?? '') !== ${JSON.stringify(String(selectedId))}`;
    const before = await signature();
    await focusStart();
    let reached = true;
    try {
      await tabToWhere(expression);
    } catch {
      reached = false;
    }
    if (!reached) {
      j.note(`${name}: every element of this class is the current selection: nothing to navigate to here`);
      continue;
    }
    await j.key("Enter", async () => ({ signatureChanged: (await signature()) !== before }), { settle: 900 });
    await untilTrue(`${name} answered`, async () => (await signature()) !== before, 30000).catch(() => {});
    check((await signature()) !== before, `navigation: Enter on « ${name} » changed nothing on screen`);
    await pause(700);
    await quiet();
  }
}
