/** An aggregate (« +N items ») is a custom widget in the SVG map: role=treeitem, focusable, Enter and Space expand it. */
async function journeyAggregate(drawnOf, brainId) {
  const j = journey("map-aggregate", "the « +N items » aggregate of the map: reached by Tab, named, expanded by Enter and by Space");
  const aggregate = '[data-testid="map-aggregate-indicator"]';
  const info = () => evaluate(`(() => { const a = document.querySelectorAll('[data-testid="map-aggregate-indicator"]'); return { aggregates: a.length, role: a[0]?.getAttribute('role') ?? null, label: a[0]?.getAttribute('aria-label') ?? null, tabindex: a[0]?.getAttribute('tabindex') ?? null }; })()`);
  const first = await info();
  check(first.role === "treeitem" && first.tabindex === "0" && (first.label ?? "").length > 0, `aggregate: not a named, focusable tree item (${JSON.stringify(first)})`);
  for (const key of ["Enter", " "]) {
    const before = { aggregates: (await info()).aggregates, cards: await drawnOf(brainId) };
    if (before.aggregates === 0) {
      j.note(`no aggregate left for ${key === " " ? "Space" : key}`);
      continue;
    }
    await focusStart();
    await j.tab(aggregate);
    const pixels = await focusIsVisibleByPixels();
    check(pixels.visibleByPixels === true, "aggregate: the focused aggregate shows no visible indicator");
    // Activating an aggregate re-projects the map around its parent (the product's own design: the parent
    // becomes the selection), so what is compared is the whole signature of the view, not a card count.
    const signature = async () => JSON.stringify({ selected: (await screenSelection()).selectedId, cards: await drawnOf(brainId), aggregates: (await info()).aggregates, status: await evaluate(`document.querySelector('.app__status')?.textContent ?? ''`) });
    const signatureBefore = await signature();
    await j.key(key, async () => ({ aggregatesBefore: before.aggregates, cardsBefore: before.cards }), { settle: 800 });
    await untilTrue("the aggregate answered", async () => (await signature()) !== signatureBefore, 30000);
    await pause(600);
    const after = { aggregates: (await info()).aggregates, cards: await drawnOf(brainId) };
    const focusAfter = short(await active());
    j.note(`${key === " " ? "Space" : key}: cards ${before.cards} → ${after.cards}, aggregates ${before.aggregates} → ${after.aggregates}; the focus is on ${focusAfter?.element}`);
    check((await signature()) !== signatureBefore, `aggregate: ${key === " " ? "Space" : key} did not activate it`);
    check(!focusAfter?.body, `aggregate: after ${key === " " ? "Space" : key} the focus fell to <body> (lost)`);
    await pause(800);
    await quiet();
  }
}
