// =========================================================================================
//  reduced motion
// =========================================================================================
/**
 * The product declares no animation or transition of its own (the inventory below proves it, in both
 * modes). What `prefers-reduced-motion` protects is any motion that would ever be added, so the proof
 * ALSO plants a probe with an inline transition and animation and shows that the product's own
 * stylesheet cancels them when the engine reports the preference — and only then.
 */
async function reducedMotionProof() {
  const inventory = () =>
    evaluate(`(() => {
      const moving = [];
      for (const e of document.querySelectorAll('body *')) {
        const cs = getComputedStyle(e);
        const hasTransition = cs.transitionDuration.split(',').some((d) => parseFloat(d) > 0) && cs.transitionProperty !== 'none';
        const hasAnimation = cs.animationName !== 'none' && cs.animationName !== '';
        const smooth = cs.scrollBehavior === 'smooth';
        if (hasTransition || hasAnimation || smooth) moving.push({ element: __t47.describe(e), transition: cs.transitionDuration, animation: cs.animationName, scrollBehavior: cs.scrollBehavior });
      }
      const root = getComputedStyle(document.documentElement);
      return { elements: document.querySelectorAll('body *').length, moving, rootScrollBehavior: root.scrollBehavior };
    })()`);
  const probe = () =>
    evaluate(`(() => {
      const el = document.createElement('div');
      el.setAttribute('data-testid', 'task0047-motion-probe');
      el.style.cssText = 'position:fixed;left:0;top:0;width:8px;height:8px;opacity:1;transition:opacity 5s linear;animation:task0047-probe 5s linear infinite;';
      const style = document.createElement('style');
      style.textContent = '@keyframes task0047-probe { from { opacity: .2 } to { opacity: 1 } }';
      document.head.appendChild(style);
      document.body.appendChild(el);
      const cs = getComputedStyle(el);
      const out = { transitionDuration: cs.transitionDuration, animationName: cs.animationName, animationDuration: cs.animationDuration, animationIterationCount: cs.animationIterationCount };
      el.remove();
      style.remove();
      return out;
    })()`);
  await setMedia({ motion: "no-preference" });
  const normal = { inventory: await inventory(), probe: await probe() };
  await setMedia({ motion: "reduce" });
  const reduced = { inventory: await inventory(), probe: await probe() };
  check(normal.probe.transitionDuration === "5s" && normal.probe.animationName === "task0047-probe", `reduced motion: the probe does not move in the normal mode (${JSON.stringify(normal.probe)}): the proof itself is broken`);
  check(reduced.probe.transitionDuration.split(",").every((d) => parseFloat(d) === 0), `reduced motion: a transition survives prefers-reduced-motion: reduce (${reduced.probe.transitionDuration})`);
  check(reduced.probe.animationName === "none", `reduced motion: an animation survives prefers-reduced-motion: reduce (${reduced.probe.animationName})`);
  check(reduced.inventory.moving.length === 0, `reduced motion: ${reduced.inventory.moving.length} element(s) still move: ${JSON.stringify(reduced.inventory.moving.slice(0, 3))}`);
  check(reduced.inventory.rootScrollBehavior !== "smooth", "reduced motion: smooth scrolling survives");
  return { normal, reduced };
}

