/** A passive window: nothing the harness does inside it may cost a backend command or move any state. */
const passiveWindows = [];
async function passive(name, fn) {
  await quiet(1200);
  const before = await stateSnapshot();
  const from = wireCalls.length;
  await stage(name, fn);
  const commands = wireCalls.slice(from).map((c) => c.command);
  await quiet(1200);
  const after = await stateSnapshot();
  const row = {
    name,
    commandsSentByTheProduct: commands,
    catalogueUnchanged: same(before.catalogue, after.catalogue),
    resumeRecordsUnchanged: same(before.resume, after.resume),
    indexAndJournalUnchanged: same(before.index, after.index),
    sourceUnchanged: same(before.source, after.source),
  };
  passiveWindows.push(row);
  check(commands.length === 0, `passive window « ${name} » caused backend commands: ${commands.join(", ")}`);
  check(row.catalogueUnchanged && row.resumeRecordsUnchanged && row.indexAndJournalUnchanged && row.sourceUnchanged, `passive window « ${name} » moved state: ${JSON.stringify(row)}`);
}

